const msgs = $('Ler emails não lidos com código PRP').all().map(i => i.json).filter(m => m && m.id);
const transp = $('Ler transportadoras').all().map(i => i.json).filter(t => t && t.id);
const props = $('Ler propostas a cotar').all().map(i => i.json).filter(p => p && p.id);
const vistos = new Set($('Ler cotações já registadas').all().map(i => i.json.email_origem_id).filter(Boolean));
const out = [];
const ignoradas = [];
for (const m of msgs) {
  const assunto = String(m.subject || '');
  const cod = (assunto.match(/PRP-\d{4}-\d{4}/i) || [])[0];
  const de = String(((m.from || {}).emailAddress || {}).address || '').toLowerCase();
  if (!cod) { ignoradas.push({ id: m.id, motivo: 'sem código PRP' }); continue; }
  if (/^\s*(\[teste\]\s*)?\[?PRP-\d{4}-\d{4}\]?\s*pedido de cota/i.test(assunto) || /^\s*\[teste\]/i.test(assunto)) { ignoradas.push({ id: m.id, motivo: 'é o nosso pedido' }); continue; }
  if (vistos.has(m.id)) { ignoradas.push({ id: m.id, motivo: 'já registada' }); continue; }
  const p = props.find(x => x.codigo === cod.toUpperCase());
  const t = transp.find(x => String(x.email || '').toLowerCase() === de);
  if (!p) { ignoradas.push({ id: m.id, motivo: 'proposta não está a_cotar' }); continue; }
  if (!t) { ignoradas.push({ id: m.id, motivo: 'remetente não é transportadora conhecida' }); continue; }
  const corpo = String((m.body && m.body.content) || m.bodyPreview || '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  out.push({ json: { email_id: m.id, codigo: p.codigo, proposta_id: p.id, transportadora_id: t.id, transportadora_nome: t.nome, assunto, texto: corpo, tem_anexos: !!m.hasAttachments, recebida_em: m.receivedDateTime || null } });
}
return out;

const base = $('Casar email com proposta e transportadora').all().map(i => i.json);
const MODOS = ['rodoviario', 'maritimo', 'aereo', 'ferroviario'];
return $input.all().map((it, idx) => {
  const b = base[idx];
  const o = (it.json && it.json.output) || {};
  const preco = typeof o.preco === 'number' && o.preco >= 0 ? o.preco : null;
  const modo = MODOS.includes(o.modo) ? o.modo : null;
  const dias = typeof o.transito_dias === 'number' && o.transito_dias >= 0 ? Math.round(o.transito_dias) : null;
  const validade = /^\d{4}-\d{2}-\d{2}$/.test(String(o.validade || '')) ? o.validade : null;
  let conf = typeof o.confianca === 'number' ? Math.min(1, Math.max(0, o.confianca)) : 0;
  const completa = preco !== null && modo !== null && dias !== null;
  const rever = !completa || conf < 0.8 || b.tem_anexos;
  if (!completa) conf = Math.min(conf, 0.5);
  return { json: { proposta_id: b.proposta_id, transportadora_id: b.transportadora_id, transportadora_nome: b.transportadora_nome, codigo: b.codigo, email_id: b.email_id, modo, preco, moeda: preco !== null ? String(o.moeda || '').slice(0, 3).toUpperCase() || null : null, transito_dias: dias, validade, condicoes: o.condicoes ? String(o.condicoes).slice(0, 500) : (b.tem_anexos ? 'Há anexos (PDF): rever manualmente' : null), confianca: conf, revisao: rever ? 'a_rever' : 'automatica', recebida_em: b.recebida_em } };
});
